import{_ as e,o as t,c as a,Q as r}from"./chunks/framework.b67c47e6.js";const o="/assets/rack-setup-form.3d60fded.svg",n="/assets/rack-load-editor.15e54922.svg",i="/assets/delivery-screen.293ddf1c.svg",s="/assets/rack-drawing.e7e4d55a.svg",b=JSON.parse('{"title":"Delivery & Racks","description":"","frontmatter":{},"headers":[],"relativePath":"guide/logistics/delivery/index.md","filePath":"guide/logistics/delivery/index.md","lastUpdated":1790346505000}'),h={name:"guide/logistics/delivery/index.md"},l=r('<h1 id="delivery-racks" tabindex="-1">Delivery &amp; Racks <a class="header-anchor" href="#delivery-racks" aria-label="Permalink to &quot;Delivery &amp; Racks&quot;">​</a></h1><p>The Delivery view is where you decide how finished panels will travel: you arrange them on racks, and that arrangement drives the order the factory produces them in.</p><nav class="table-of-contents"><ul><li><a href="#delivery-dates">Delivery dates</a></li><li><a href="#when-to-use-it">When to use it</a></li><li><a href="#two-things-with-two-names">Two things with two names</a></li><li><a href="#rack-setups">Rack setups</a></li><li><a href="#building-a-rack-load">Building a rack load</a><ul><li><a href="#reading-the-capacity-bars">Reading the capacity bars</a></li></ul></li><li><a href="#setting-the-production-order">Setting the production order</a></li><li><a href="#the-delivery-screen">The Delivery screen</a><ul><li><a href="#the-list">The list</a></li><li><a href="#working-a-rack">Working a rack</a></li><li><a href="#scanning">Scanning</a></li></ul></li><li><a href="#marking-panels-as-loaded">Marking panels as loaded</a></li><li><a href="#printing-rack-labels">Printing rack labels</a></li><li><a href="#strapped-rows">Strapped rows</a></li><li><a href="#overhang">Overhang</a></li><li><a href="#the-rack-drawing">The rack drawing</a></li></ul></nav><h2 id="delivery-dates" tabindex="-1">Delivery dates <a class="header-anchor" href="#delivery-dates" aria-label="Permalink to &quot;Delivery dates&quot;">​</a></h2><p>A rack load has a <strong>delivery date</strong>: when it is due on site. Fill it in and the Delivery screen sorts by it, soonest first, and marks anything past its date and not yet delivered as <strong>Late</strong>.</p><p>Leave it empty while the load is only a plan. An undated rack sorts last and is never late.</p><h2 id="when-to-use-it" tabindex="-1">When to use it <a class="header-anchor" href="#when-to-use-it" aria-label="Permalink to &quot;When to use it&quot;">​</a></h2><p>Rack planning happens <strong>before</strong> production, not after:</p><ol><li>You arrange the racks the way the panels need to ship and be built on site.</li><li>That arrangement sets the production order.</li><li>The factory produces the panels.</li><li>Workers mark each panel as loaded on its rack as it comes off the line.</li></ol><p>So the panels you are arranging have not been made yet. That is normal, and the view shows their real status without treating &quot;waiting&quot; as a problem.</p><h2 id="two-things-with-two-names" tabindex="-1">Two things with two names <a class="header-anchor" href="#two-things-with-two-names" aria-label="Permalink to &quot;Two things with two names&quot;">​</a></h2><ul><li>A <strong>rack setup</strong> is a kind of rack your factory owns — an A-frame, a wall rack, a flat bed. You own several identical ones of each; the app does not track which physical unit gets used.</li><li>A <strong>rack load</strong> is one rack filled with panels for one project.</li></ul><h2 id="rack-setups" tabindex="-1">Rack setups <a class="header-anchor" href="#rack-setups" aria-label="Permalink to &quot;Rack setups&quot;">​</a></h2><p>Manage them from <strong>Rack setups</strong> in the company section of the menu (it is there when your company has the delivery module). Press <strong>New rack</strong> to add one.</p><table><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Name</strong></td><td>What people call this kind of rack.</td></tr><tr><td><strong>Loading pattern</strong></td><td><strong>A-frame, both sides</strong>, <strong>Single side</strong>, or <strong>Flat bed</strong>.</td></tr><tr><td><strong>Strapped rows</strong></td><td>Which rows are tied to the frame. See below.</td></tr><tr><td><strong>Usable length</strong></td><td>How long a row can be. Panels placed side by side have to fit in it.</td></tr><tr><td><strong>Stack depth per side</strong></td><td>How much thickness you can stack away from the frame.</td></tr><tr><td><strong>Max panel height</strong></td><td>The tallest panel the rack takes.</td></tr><tr><td><strong>Max overhang per end</strong></td><td>How far a row may stick out past each end of the rack.</td></tr></tbody></table><p>The list also shows how many loads use each setup.</p><p>The sizes are guides, not rules. The app warns when a load goes over them and lets you carry on.</p><p><img src="'+o+'" alt="The rack setup form"></p><ol><li>The loading pattern decides which rows exist.</li><li>The diagram follows your choices: the orange bar is the rack, the strapped rows are blue with a padlock.</li><li><strong>Strapped rows</strong>. See <a href="#strapped-rows">Strapped rows</a>.</li><li>The sizes, in mm. See <a href="#overhang">Overhang</a> for the last one.</li></ol><p>When a rack goes out of service, <strong>archive</strong> it with the archive button on its row. It disappears from the dropdowns and every load ever made with it keeps working. The <strong>Archived</strong> button at the top shows archived setups again. Deleting is only possible for a setup no load has ever used.</p><h2 id="building-a-rack-load" tabindex="-1">Building a rack load <a class="header-anchor" href="#building-a-rack-load" aria-label="Permalink to &quot;Building a rack load&quot;">​</a></h2><p>In the project menu, <strong>Delivery</strong> opens the planning view, with one card per rack load. Press <strong>New rack load</strong>, or <em>Edit</em> in the menu of an existing card. The editor opens in three columns: <strong>Load details</strong>, <strong>Panels to load</strong>, and the rack.</p><ol><li>Pick the <strong>Rack setup</strong> on the left. The <code>+</code> button next to it creates a new setup on the spot.</li><li>Filter the panel list in the middle by production line, phase, batch or scheduled date. Those fields are a filter, not part of the load — they sit in their own boxed <strong>Filter the panels</strong> block, with a <strong>Clear</strong> button and the count of what is left underneath.</li><li>Click a panel to put it on the rack.</li><li>Drag panels to reorder them. Drag two into the same row to place them side by side. Drag onto the strip marked <code>+</code> to start a new row.</li><li>Fill in the description, the location, the <strong>delivery date</strong> and, if you use it, a status, in the first column. The status is free text.</li><li>Press <strong>Save load</strong>.</li></ol><p>Rows tied to the frame are marked with a padlock. Which ones those are comes from the rack setup — see <strong>Strapped rows</strong> below.</p><p><img src="'+n+'" alt="The rack load editor"></p><ol><li>The rack setup, with <code>+</code> to create one on the spot.</li><li>The filter of the panel list. It is not part of the load.</li><li>The panels that can still be added. Click one to put it on the rack.</li><li>A strapped row, marked with a padlock.</li><li>The capacity bar of a row. Orange here: the row hangs over the ends, within the allowance.</li><li>The orange question mark: this design has not been analysed, so its size is a placeholder. The vertical arrows on <em>W-14</em> mean it is taller than the rack takes.</li><li>Drop a panel here to start a new row.</li></ol><h3 id="reading-the-capacity-bars" tabindex="-1">Reading the capacity bars <a class="header-anchor" href="#reading-the-capacity-bars" aria-label="Permalink to &quot;Reading the capacity bars&quot;">​</a></h3><p>Each row has a bar showing how much of the rack length it uses, and each side shows how deep the stack has got. Green is fine, orange is close (over 85 %) or hanging over within the allowance, red is over. Nothing is blocked: you decide what fits.</p><p>A panel taller than the rack takes gets an orange vertical-arrows icon. If a panel on the rack shows an orange question mark, its design has not been analysed yet, so the app is drawing it at a placeholder size. Run the analysis to see the real one.</p><h2 id="setting-the-production-order" tabindex="-1">Setting the production order <a class="header-anchor" href="#setting-the-production-order" aria-label="Permalink to &quot;Setting the production order&quot;">​</a></h2><p>This is done where production order already lives: the <strong>panel sorting dialog of a batch</strong>. There you get a <strong>Sort by rack loading</strong> button, which arranges the panels the way their racks get loaded — load by load, and inside each one starting from the row against the frame. Each panel also shows a small chip with its rack and its position on it, so you can check the order against the plan before saving.</p><h2 id="the-delivery-screen" tabindex="-1">The Delivery screen <a class="header-anchor" href="#the-delivery-screen" aria-label="Permalink to &quot;The Delivery screen&quot;">​</a></h2><p>Delivery is a mode of its own, next to Logistics and Production. Pick it in the mode buttons at the top of the left menu and you get the racks instead of the panels: a row per rack load with how far along it is, and the rack itself when you tap one.</p><p>The mode is there for managers, admins and production users when your company has the delivery module.</p><p>It is built for a tablet standing next to the rack. Everything is a button you can see — there are no menus to open and nothing hidden behind a long press.</p><h3 id="the-list" tabindex="-1">The list <a class="header-anchor" href="#the-list" aria-label="Permalink to &quot;The list&quot;">​</a></h3><p>Three tiles at the top filter it: <strong>All</strong>, <strong>To load</strong> and <strong>To deliver</strong> — the two jobs a rack still has left on it. Each tile shows how many loads it holds. Tap one to filter, tap it again to clear it.</p><p>Each row shows the load&#39;s description, delivery date, rack setup and location, and a bar with where its panels are: green for delivered, blue for in the rack, orange for still to load. The state (<strong>EMPTY</strong>, <strong>TO LOAD</strong>, <strong>LOADING</strong>, <strong>LOADED</strong> or <strong>DELIVERED</strong>) is written across the bar, with your own status note in brackets after it and the count of loaded panels at the end. A rack past its delivery date shows its date in red.</p><p>Pick <strong>All projects</strong> at the top and you get every rack the company owes anyone, soonest first, grouped by project.</p><p><img src="'+i+'" alt="The Delivery screen on a tablet, with a rack load open"></p><ol><li><strong>Delivery</strong> in the mode buttons. With four modes, the productive ones share the right half: tap it to switch.</li><li>The filter tiles, with a count each.</li><li>A rack load: its bar, its state and how many panels are loaded.</li><li>A load past its delivery date shows the date in red.</li><li>The rack drawing. Tapping a panel points at its row in the list.</li><li>The three state buttons of each panel.</li><li>The buttons for the whole rack.</li></ol><h3 id="working-a-rack" tabindex="-1">Working a rack <a class="header-anchor" href="#working-a-rack" aria-label="Permalink to &quot;Working a rack&quot;">​</a></h3><p>Tap a rack to open it. You get the load&#39;s details and delivery status at the top, then the drawing, the panel list and the buttons.</p><p><strong>Each panel has its own three buttons: Not loaded, In rack, Delivered.</strong> One tap sets the state. Nothing asks you to confirm: if you tap the wrong one, tap the right one.</p><p>Tapping a panel in the drawing points at its row in the list. The drawing is the map; the list is where you work.</p><p>Along the bottom, three buttons for the whole rack: <strong>Unload all</strong>, <strong>Mark all loaded</strong> and <strong>All delivered</strong>. Only <em>Unload all</em> asks first — the other two are undone by the button next to them in one tap. Managers also get <strong>Edit</strong> at the top right, next to the refresh button, to change the arrangement.</p><p>Printing the stickers stays in Reports, where it was: it is not something you do standing at a rack.</p><h3 id="scanning" tabindex="-1">Scanning <a class="header-anchor" href="#scanning" aria-label="Permalink to &quot;Scanning&quot;">​</a></h3><p>With a rack open, scanning a panel&#39;s QR marks that panel as in the rack instead of opening it — which is what you want with the panel in your hands. If the panel is not on this load, the app says so and changes nothing. Scan with no rack open, or scan any other code, and it works as always.</p><h2 id="marking-panels-as-loaded" tabindex="-1">Marking panels as loaded <a class="header-anchor" href="#marking-panels-as-loaded" aria-label="Permalink to &quot;Marking panels as loaded&quot;">​</a></h2><p>Once panels come off the line, mark them:</p><ul><li><strong>On the whole rack</strong> — <em>Mark all loaded</em> or <em>All delivered</em> from the Delivery screen, or <em>Mark all loaded</em> and <em>Mark delivered</em> on the load&#39;s card in the planning view. <em>Unload all</em>, on the Delivery screen, puts them all back.</li><li><strong>One panel at a time</strong> — the three buttons on its row in the Delivery screen, or the rack button in the <a href="/guide/viewer/">Viewer</a>.</li></ul><p>This is what fills the delivery chart on the dashboard, so it is worth doing.</p><h2 id="printing-rack-labels" tabindex="-1">Printing rack labels <a class="header-anchor" href="#printing-rack-labels" aria-label="Permalink to &quot;Printing rack labels&quot;">​</a></h2><p>Generate <a href="/guide/reports/qr_stickers/">Rack Load Stickers</a> for a load. One rack per A4 sheet, landscape. The QR takes the whole left half of the sheet, so it can be scanned from across the workshop and at an angle. Beside it: the load name, the rack and its loading pattern, the project, the project number, the client, the location, the drawing, and the panels in loading order with the strapped rows marked.</p><p>The delivery date is printed large, above the project: it is what the driver looks for. A rack with no date yet simply leaves it out.</p><p>Scanning the QR opens the rack on a phone or tablet, with the drawing, the panel list and the buttons. Stickers printed before this change still work.</p><h2 id="strapped-rows" tabindex="-1">Strapped rows <a class="header-anchor" href="#strapped-rows" aria-label="Permalink to &quot;Strapped rows&quot;">​</a></h2><p>Some racks tie the first row down to the frame. Those panels are loaded first and come off last, and the app marks them wherever they appear: with a blue padlock in the editor, in the Delivery screen and in the drawing, and on the printed sticker with a blue row in the drawing and a dot in the panel list.</p><p>Which rows are strapped is part of the <strong>rack setup</strong>, because it depends on the rack you own:</p><ul><li><strong>Flat bed</strong> — nothing is strapped. There is no frame to tie anything to, so there is nothing to choose.</li><li><strong>Single side</strong> — <strong>A0</strong> (the first row) or <strong>None</strong>.</li><li><strong>A-frame</strong> — <strong>A0</strong>, <strong>B0</strong>, <strong>A0 and B0</strong>, or <strong>None</strong>.</li></ul><p>The little diagram in the rack setup form shows it as you pick: the strapped row turns blue and gets the padlock, and the rack itself is the orange bar labelled <strong>RACK</strong>.</p><p>Existing rack setups keep marking their first row, which is what they did before this was a choice — except flat beds, which now correctly mark nothing.</p><h2 id="overhang" tabindex="-1">Overhang <a class="header-anchor" href="#overhang" aria-label="Permalink to &quot;Overhang&quot;">​</a></h2><p>Panels sit <strong>centred</strong> on the rack, so a row wider than the rack sticks out at both ends by the same amount. How far it may stick out is part of the rack setup: <strong>Max overhang per end</strong>.</p><p>The bar under each row tells you where you are — green while the row fits on the rack, orange once it hangs over but stays within the allowance, and red when it goes past it. It still lets you save: as with the other rack dimensions, it warns and you decide.</p><p>A setup with the overhang left at 0 behaves exactly as before: anything wider than the rack is over capacity.</p><h2 id="the-rack-drawing" tabindex="-1">The rack drawing <a class="header-anchor" href="#the-rack-drawing" aria-label="Permalink to &quot;The rack drawing&quot;">​</a></h2><p>The same drawing appears wherever the load does — the card, the rack&#39;s page, the rack button in the viewer, and the printed sticker. One band per row in loading order, panels at their real sizes, the strapped row highlighted, and the frame where it physically sits.</p><p>Each panel is drawn at its real width along the rack, with its name and its width × height × thickness written on it. On the printed sticker the panels are drawn as cross-sections, so their thickness into the stack is to scale too. On screen each panel also shows its priority within its batch as <code>number/total</code>, and a round badge once it is loaded (blue) or delivered (green).</p><p>Rows are centred and the frame is drawn at the rack&#39;s real length, so an overhang is visible rather than implied; dashed guides mark where the rack ends.</p><p>It is drawn from the arrangement itself, so it is never out of date with what you saved.</p><p><img src="'+s+'" alt="An A-frame rack drawing, with its capacity bars"></p><ol><li>A strapped row: tinted blue, with a padlock.</li><li>The frame, drawn at the rack&#39;s real length. Side B is above it, side A below.</li><li>The dashed guides mark where the rack ends.</li><li>This row is wider than the rack and sticks out at both ends.</li><li>The badge of a loaded (blue) or delivered (green) panel.</li><li>The capacity bars of the editor: red past the allowance, orange close to it or hanging over within it, green when it fits.</li></ol>',74),d=[l];function c(p,g,w,u,k,m){return t(),a("div",null,d)}const y=e(h,[["render",c]]);export{b as __pageData,y as default};
